test.config:
indexer
{
	mem_limit = 16M
}

searchd
{

}

source e1_source
{
	type = mysql

	sql_query = SELECT id, title, body, gid FROM e1_docs ORDER BY id
	sql_attr_uint = gid
}

index e1_plain
{
	source = e1_source
	path = /e1_plain
	index_field_lengths = 1
}

index norms_plain
{
	source = e1_source
	path = /norms_plain
}

index e1_rt
{
	type = rt
	path = /e1_rt
	rt_field = title
	rt_field = body
	rt_attr_uint = gid
}

index e1_ties
{
	type = rt
	path = /e1_ties
	rt_field = body
}

index e1_direct_rt
{
	type = rt
	path = /e1_direct_rt
	rt_field = title
	rt_field = body
	rt_attr_uint = gid
}

index e1_attrs_only
{
	type = rt
	path = /e1_attrs_only
	rt_attr_uint = gid
}

queries.sphinxql:
INSERT INTO e1_rt (id,title,body,gid) VALUES
(1,'alpha alpha beta','gamma',1),
(2,'alpha','alpha alpha gamma',1),
(3,'beta gamma','alpha',2);
SELECT id,weight() AS w FROM e1_rt WHERE MATCH('alpha') ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_rt WHERE MATCH('alpha') ORDER BY w DESC,id ASC OPTION ranker=expr('1000*bm25a(1.2,0.75,256)+0');
FLUSH RAMCHUNK e1_rt;
INSERT INTO e1_rt (id,title,body,gid) VALUES
(4,'alpha beta','beta alpha',2),
(5,'gamma','beta',3),
(6,'alpha alpha alpha','alpha beta gamma',3);
FLUSH RAMCHUNK e1_rt;
INSERT INTO e1_ties (id,body) VALUES (30,'tie'),(20,'tie'),(10,'tie');
FLUSH RAMCHUNK e1_ties;


INSERT INTO e1_direct_rt (id,title,body,gid) VALUES
(101,'alpha','beta',1),(102,'alpha alpha','gamma',1),(103,'beta','alpha',1);
INSERT INTO e1_direct_rt (id,title,body,gid) VALUES
(104,'gamma alpha','beta',2),(105,'alpha','alpha beta',2),(106,'beta alpha','gamma',2);
INSERT INTO e1_direct_rt (id,title,body,gid) VALUES
(107,'alpha beta','alpha',3),(108,'gamma','alpha alpha',3),(109,'alpha','gamma',3);
SHOW TABLE e1_direct_rt STATUS LIKE 'ram_chunk_segments_count';
DELETE FROM e1_direct_rt WHERE id IN (101,105,109);
SELECT id,weight() AS w FROM e1_direct_rt WHERE MATCH('alpha') ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_direct_rt WHERE MATCH('alpha') ORDER BY w DESC,id ASC OPTION ranker=expr('1000*bm25a(1.2,0.75,256)+0');
FLUSH RAMCHUNK e1_direct_rt;
SELECT id,weight() AS w FROM e1_direct_rt WHERE MATCH('alpha') ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_direct_rt WHERE MATCH('alpha') ORDER BY w DESC,id ASC OPTION ranker=expr('1000*bm25a(1.2,0.75,256)+0');


INSERT INTO e1_attrs_only (id,gid) VALUES (201,1),(202,2),(203,3);
DELETE FROM e1_attrs_only WHERE id=202;
FLUSH RAMCHUNK e1_attrs_only;
SELECT id,gid FROM e1_attrs_only ORDER BY id ASC;



SELECT id FROM e1_plain WHERE MATCH('alpha') ORDER BY weight() DESC,id ASC;
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('alpha') ORDER BY w DESC,id ASC;
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('alpha beta') ORDER BY w DESC,id ASC;
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('alpha | beta | gamma | missing') ORDER BY w DESC,id ASC;
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('alpha | beta | gamma | missing') ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id FROM e1_plain WHERE MATCH('alpha') ORDER BY id ASC;
SELECT id FROM e1_plain WHERE MATCH('alpha') ORDER BY id ASC OPTION ranker=none;
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('alpha') ORDER BY id ASC;
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('alpha') ORDER BY WEIGHT() DESC, ID ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('alpha') ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('alpha') ORDER BY w DESC,id ASC OPTION ranker=expr('1000*bm25a(1.2,0.75,256)');
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('@title alpha') ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('@body alpha') ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('alpha beta') ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('alpha | beta') ORDER BY w DESC,id ASC LIMIT 2,3 OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('"alpha beta"') ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('alpha') AND gid=2 ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('alpha') AND gid=2 LIMIT 1; SHOW META LIKE 'total_found';
SELECT COUNT(*) FROM e1_plain WHERE MATCH('alpha') AND gid=2;


SELECT id,weight() AS w FROM e1_plain WHERE MATCH('(alpha NEAR/2 beta)') ORDER BY w DESC,id ASC OPTION ranker=bm25a; SHOW META LIKE 'total_found';
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('(alpha NEAR/2 beta)') ORDER BY w DESC,id ASC OPTION ranker=expr('1000*bm25a(1.2,0.75,256)'); SHOW META LIKE 'total_found';
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('alpha MAYBE beta') ORDER BY w DESC,id ASC OPTION ranker=bm25a; SHOW META LIKE 'total_found';
